  au=', '.join(authors[:6])+(' et al.' if len(authors)>6 else '')
  title=html.unescape(re.sub('<[^>]+>','',a.get('title',[''])[0])).replace('inR','in R');venue=a.get('container-title',[''])[0] if a.get('container-title') else ''
  date=a.get('published-print',a.get('published',a.get('issued',{}))).get('date-parts',[[None]])[0][0]
